    }
    if (!file.exists()) {
        throw new IOException("File does not exist: " + file);
    }
    if (file.isDirectory()) {
        java.util.List<File> toDelete = new java.util.ArrayList<>();
        java.nio.file.Files.walkFileTree(file.toPath(), new java.nio.file.SimpleFileVisitor<java.nio.file.Path>() {
            @Override
