                                                                   IOException exc) throws IOException {
                toDelete.add(dirPath.toFile());
                return java.nio.file.FileVisitResult.CONTINUE;
            }
        });
        for (File f : toDelete) {
            f.deleteOnExit();
        }
    } else {
        file.deleteOnExit();
    }
