    List<E> orderedEdges = new ArrayList<>();
    Set<E> visited = new HashSet<>();
    V current = start;
    while (current != null && !visited.contains(edgeMap.get(current))) {
        E e = edgeMap.get(current);
        if (e == null) {
            break;
        }
        if (visited.contains(e)) {
            break;
        }
        orderedEdges.add(e);
        visited.add(e);
        current = graph.getEdgeTarget(e);
        // If we are back to the start in a cycle, stop after adding last edge
        if (current != null && current.equals(start)) {
            break;
        }
    }
    if (orderedEdges.isEmpty()) {
        return null;
    }
    V target = graph.getEdgeTarget(orderedEdges.get(orderedEdges.size() - 1));
    double totalWeight = 0.0;
    for (E e : orderedEdges) {
        totalWeight += graph.getEdgeWeight(e);
    }
    return new org.jgrapht.graph.DefaultGraphPath<>(graph, start, target, orderedEdges, totalWeight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();
    if(edgeList.isEmpty()){
        return new GraphPathImpl<>(graph, null, null, vertexList, edgeList);
    }
    // start from any edge
    E startEdge = edgeList.remove(0);
    V current = graph.getEdgeSource(startEdge);
    vertexList.add(current);
    List<E> orderedEdges = new ArrayList<>();
    orderedEdges.add(startEdge);
    // keep traversing while we can find an edge whose source matches the current vertex
    while(!edgeList.isEmpty()){
        boolean found = false;
        for(int i=0;i<edgeList.size();i++){
            E e = edgeList.get(i);
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if(src.equals(current)){
                orderedEdges.add(e);
                current = tgt;
                vertexList.add(current);
                edgeList.remove(i);
                found = true;
                break;
            }
            // For undirected graphs, allow either direction
            if(tgt.equals(current)){
                // reverse the edge by treating target as source
                orderedEdges.add(e);
                current = src;
                vertexList.add(current);
                edgeList.remove(i);
                found = true;
                break;
            }
        }
        if(!found){
            break; // cannot extend further
        }
    }
    V source = vertexList.isEmpty() ? null : vertexList.get(0);
    V target = vertexList.isEmpty() ? null : vertexList.get(vertexList.size()-1);
    return new GraphPathImpl<>(graph, source, target, vertexList, orderedEdges);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) return null;
    java.util.List<E> order = new java.util.ArrayList<>(tour);
    return new GraphPath<>(graph, order);
}

