            sorted.add((Integer) k);
        } else {
            // If the key is not an Integer, default to 0 (or handle appropriately)
            sorted.add(0);
        }
    }
    Collections.sort(sorted);
    // For each key in the original list, find the maximum lower bound
    for (K k : keys) {
        int key;
        if (k instanceof Integer) {
            key = (Integer) k;
        } else {
            key = 0;
        }
        int idx = Collections.binarySearch(sorted, key);
        if (idx < 0) {
            // key not found, insertion point gives the index where it would be inserted
            int insertionPoint = -idx - 1;
            int lowerIdx = insertionPoint - 1;
            bounds.add(lowerIdx >= 0 ? sorted.get(lowerIdx) : Integer.MIN_VALUE);
