public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> result = new ArrayList<>();
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return result;
    }
    int start = path.startsWith("/") ? 1 : 0;
    int pos = start;
    while (pos < path.length()) {
        int nextSlash = path.indexOf('/', pos);
        if (nextSlash == -1) {
            nextSlash = path.length();
        }
        String seg = path.substring(pos, nextSlash);
        if (decode && !seg.isEmpty()) {
            try {
                seg = java.net.URLDecoder.decode(seg, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                // ignore, keep the original segment
            }
        }
        result.add(new PathSegmentImpl(seg, !decode));
        pos = nextSlash + 1;
    }
    return result;
}

