public static String applyRelativePath(String path, String relativePath) {
    boolean leadingSlash = path != null && path.startsWith("/");
    String[] baseParts = path != null ? path.split("/") : new String[0];
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();

    // Push base path components onto stack
    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        stack.addLast(part);
    }

    // Apply relative path components
    if (relativePath != null) {
        String[] relParts = relativePath.split("/");
        for (String part : relParts) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            } else if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.removeLast();
                }
            } else {
                stack.addLast(part);
            }
        }
    }

    // Build resulting path
    StringBuilder result = new StringBuilder();
    if (leadingSlash) {
        result.append('/');
    }
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append('/');
        }
    }

    // If result is empty but originally had a leading slash, keep root slash
    if (result.length() == 0 && leadingSlash) {
        result.append('/');
    }

    return result.toString();
}

