    if (root == null) return 0;
    int removed = 0;
    java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {
        Category current = stack.pop();
        java.util.Iterator<Category> it = current.getChildren().iterator();
        while (it.hasNext()) {
            Category child = it.next();
            if (!child.isActive()) {
                it.remove();
                removed++;
            } else {
                stack.push(child);
            }
        }
    }
    return removed;
}

protected int removeUnusedNodes(){
    int removed = 0;
    if (root == null) {
        return 0;
    }
    java.util.Deque<Category[]> stack = new java.util.ArrayDeque<>();
    for (Category child : root.getChildren()){
        stack.push(new Category[]{child, root});
    }
    while (!stack.isEmpty()){
        Category[] pair = stack.pop();
        Category node = pair[0];
        Category parent = pair[1];
        if (node.isInactive()){
            parent.removeChild(node);
            removed++;
        } else {
            for (Category child : node.getChildren()){
                stack.push(new Category[]{child, node});
            }
        }
    }
    return removed;
}

