protected List<TimeRange> buildTimeRanges(long start,long end){
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long current = start;
    while (current < end) {
        long remaining = end - current;
        long duration = Math.min(remaining, FETCH_DATA_DURATION);
        ranges.add(new TimeRange(current, current + duration));
        current += duration;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end){
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long cursor = start;
    long remaining = end - start;
    while (remaining > 0) {
        long chunk = Math.min(remaining, FETCH_DATA_DURATION);
        ranges.add(new TimeRange(cursor, cursor + chunk));
        cursor += chunk;
        remaining -= chunk;
    }
    return ranges;
}

