        boolean isPrime = true;
        for (int i = 3; i * i <= candidate; i += 2){
            if (candidate % i == 0){
                isPrime = false;
                break;
            }
        }
        if (isPrime){
            return candidate;
        }
        candidate += 2;
    }
}

